/* normaliseConnectorId twin — lowercases and strips _/- so oc_foo, foo-bar
 * and Foo all resolve to the same mark. */
export function getConnectorIconMarkup(id: unknown): string {
  const key = String(id || "").toLowerCase().replace(/[_-]/g, "");
  if (!key) return "";
  return CONNECTOR_MARKS[key] || CONNECTOR_MARKS[String(id || "").toLowerCase()] || "";
}
